/// Back/forward replay of a full `NavLocation`: select the workroom, focus the tab, then put the
/// recorded content back on screen.
///
/// **Replay never creates a tab.** Back ignores anything that was closed and nothing is ever
/// reopened, so the payload has to land in a tab that already exists. `isLive` has already rejected
/// any entry with nowhere to land, which is why the last branch is unreachable rather than a spawn:
///
/// ```
///   applyLocation(loc)
///     │ select loc.target, focus loc.tab  (suppressed, so nothing re-records)
///     ├── contentID == nil ─▶ a terminal ─▶ done: the focus above IS the whole replay
///     └── contentID != nil ─▶ the payload must land in an EXISTING tab:
///           ├─ 1. loc.tab still shows it            ─▶ nothing to re-open, it is already there
///           ├─ 2. some other live tab shows it       ─▶ focus that tab (the ⌘D twin / a pinned copy)
///           ├─ 3. a preview slot exists              ─▶ retarget it IN PLACE (the common case:
///           │                                            the shared preview tab drifted as you browsed)
///           └─ 4. otherwise                          ─▶ UNREACHABLE — isLive skipped this entry
///         then: reinstate the in-commit file selection, and refresh a diff's stale change kind
/// ```
private func applyLocation(_ loc: NavLocation, recordHistory: Bool) {
  applyLocation(target: loc.target, tab: loc.tab, recordHistory: recordHistory)
  guard let payload = loc.payload, let target = selectedTarget, !target.isMissing else { return }
  withHistorySuppressed {
    // A diff's `change` is rendered (the header letter) and acted on ("Open file in…" is disabled for
    // a deleted source), so replaying a record-time value could offer to open a file that is gone.
    // Take the live kind from the same changed-file list the Changes panel renders; keep the recorded
    // one when status has not loaded yet.
    let landing = Self.refreshingChangeKind(payload, from: workroomStatuses[loc.target])

    let landedTab: TerminalTab.ID?
    if let recorded = terminals.tab(loc.tab, for: target), landing.matchesTab(recorded.content) {
      landedTab = recorded.id  // 1 — already showing it
    } else if let other = terminals.tabs(for: target).first(where: {
      landing.matchesTab($0.content)
    }) {
      terminals.focus(other.id, for: target)
      landedTab = other.id  // 2 — a different tab has it
    } else if terminals.hasPreviewTab(for: target) {
      landedTab = landing.openAsPreview(in: terminals, for: target)  // 3 — retarget in place
    } else {
      landedTab = nil  // 4 — nowhere to land; isLive should have skipped this entry
    }

    if case .changeset = landing, let landedTab {
      terminals.setChangesetSelectedPath(loc.selectedPath, forTab: landedTab, in: target)
    }
  }
}

/// A payload with a `.diff`'s change kind refreshed from live status; everything else unchanged.
/// `nonisolated` + pure so the freshness rule is unit-testable without a store.
nonisolated static func refreshingChangeKind(_ payload: NavPayload, from status: WorkroomStatus?)
  -> NavPayload
{
  guard case .diff(var descriptor) = payload else { return payload }
  // `changedFiles` mirrors the jj working copy's own file list, so this one lookup covers git
  // worktree and jj `@` alike. A commit diff is immutable, so it is deliberately not refreshed.
  guard case .gitWorktree = descriptor.source else {
    if case .jjWorkingCopy = descriptor.source {} else { return payload }
    return refreshed(&descriptor, status)
  }
  return refreshed(&descriptor, status)
}

private nonisolated static func refreshed(
  _ descriptor: inout DiffDescriptor, _ status: WorkroomStatus?
) -> NavPayload {
  guard let live = status?.changedFiles?.first(where: { $0.path == descriptor.path }) else {
    return .diff(descriptor)
  }
  descriptor.change = live.change
  return .diff(descriptor)
}

/// Whether a recorded location is still reachable *without creating anything* — the mechanism behind
/// "back ignores what was closed". `step(_:isLive:)` skips every entry this rejects.
///
/// A terminal entry needs its own tab: there is nothing else to show. A content entry needs somewhere
/// to land — a tab already showing it, or a preview slot to retarget — AND its recorded tab must
/// still exist, because `prune` keys on the tab id and an entry that outlived its tab is one the user
/// closed. Deliberately does NOT ask whether the file or commit still exists on disk: that needs I/O
/// inside a predicate run per candidate while stepping, and the pane already renders its own
/// "Diff unavailable" / "Changeset unavailable" state.
private func isLive(_ loc: NavLocation) -> Bool {
  guard let target = target(for: loc.target), !target.isMissing else { return false }
  let tabs = terminals.tabs(for: target)
  guard tabs.contains(where: { $0.id == loc.tab }) else { return false }
  guard let payload = loc.payload else { return true }
  return tabs.contains { payload.matchesTab($0.content) } || terminals.hasPreviewTab(for: target)
}

