/// `isLive`'s acceptance path via the FIRST clause: a content entry is reachable because its own tab
/// still shows it, with no preview slot anywhere. Reducing the `||` to just `hasPreviewTab` would make
/// back/forward silently dead once every tab is pinned, and nothing else in the suite would fail.
func testForwardReachesAPinnedContentEntryWithNoPreviewSlot() {
  let store = makeStore([project("/a", workrooms: ["main"])])
  let a = SidebarID.workroom(project: "/a", name: "main")
  let targetA = store.target(for: a)!
  let term = addTerminal(store, a)
  store.openDiffPreview(ChangedFile(path: "A.swift", change: .modified), source: .gitWorktree)
  store.openDiffPreview(ChangedFile(path: "B.swift", change: .modified), source: .gitWorktree)
  let tab = store.terminals.focusedTab(for: targetA)!.id
  store.terminals.persist(tab, for: targetA)  // no preview slot left

  store.navigateBack()  // A.swift is unreachable → skipped, lands on the terminal
  XCTAssertEqual(store.terminals.focusedTab(for: targetA)?.id, term)

  store.navigateForward()

  guard case .diff(let d)? = store.terminals.focusedTab(for: targetA)?.content else {
    return XCTFail("Forward must reach the pinned diff")
  }
  XCTAssertEqual(d.path, "B.swift", "live because its own tab still shows it, not via a preview slot")
}

